<?php

namespace Tests;

use Illuminate\Foundation\Testing\TestCase as BaseTestCase;
use Illuminate\Http\UploadedFile;

abstract class TestCase extends BaseTestCase
{
    protected function gambarPalsu(string $nama = 'foto.jpg'): UploadedFile
    {
        $png = str_ends_with(strtolower($nama), '.png');
        $isi = base64_decode($png ? self::PNG : self::JPG);

        return UploadedFile::fake()->createWithContent($nama, $isi);
    }

    private const JPG = '';

    private const PNG = 'iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAFklEQVR4nGMUz1zFwMDAxMDAwMDAAAANjwEuayoTOQAAAABJRU5ErkJggg==';
}
